contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function holding all test logic
    // params: sender is the test caller, we supply amount to deposit
    function runTest(uint256 depositAmount) public {
        // ensure the test actor (this contract) has enough ETH if a deposit will send value
        // (caller of runTest must have funded this contract externally if needed)
        require(depositAmount == 0 || address(this).balance >= depositAmount);

        // read balance before
        uint256 before = c.balances(address(this));

        // perform deposit on target contract, sending depositAmount wei
        c.deposit{value: depositAmount}();

        // read balance after
        uint256 after = c.balances(address(this));

        // The original contract C used assert(balances + msg.value > balances) which prevents accepting 0-value deposits.
        // So on P, depositing 0 must not leave the balance unchanged (this enforces that zero-value deposits are rejected by assert).
        // On the mutant M (which uses >=), depositing 0 will be allowed and after == before, violating this assertion.
        assert(depositAmount != 0 || after > before);
    }

    // allow this test contract to receive ETH for making deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition needed
        // attempt a zero-value deposit
        bool reverted; try c.deposit{value: 0}() { reverted = false; } catch { reverted = true; }
        // In the original contract, depositing 0 reverts due to assert preventing non-strict increase;
        // the mutant allows zero deposits, so we assert that the zero deposit must revert.
        assert(reverted);
    }
    receive() external payable { }
}

