pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: actor and an amount. We must let the fuzzer choose values.
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep actor non-zero address to be a valid EOA in fuzzing
        vm.assume(actor != address(0));
        // Keep amount within a practical bound so vm.deal works
        amount = bound(amount, 0, 1 ether);

        // Fund the actor so they can call deposit with `amount` wei
        vm.deal(actor, amount);

        // Capture contract balance and later compare
        uint256 beforeContractBal = address(c).balance;

        // Perform deposit as the fuzzed actor sending `amount` wei
        vm.prank(actor);
        c.deposit{value: amount}();

        uint256 afterContractBal = address(c).balance;

        // General rule (single assertion): If amount == 0 then contract balance must be unchanged.
        // The correct contract ensures that a zero-value deposit does not alter stored balances/contract balance;
        // the mutant that changed `assert(... > ...)` to `require(... >= ...)` can accept zero-value deposits and
        // thus may make address(c).balance increase for some inputs (specifically when amount == 0 in contexts
        // where ethers are transferred in). We assert the universal property on the reference implementation.
        if (amount == 0) {
            assertTrue(afterContractBal == beforeContractBal);
        } else {
            // For non-zero amounts, at least the contract balance must have increased by amount.
            assertTrue(afterContractBal == beforeContractBal + amount);
        }
    }
}

