pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the actor and two amounts: a nonzero amount to establish a positive balance,
    // and a second amount which we will fuzz and allow to be zero. The property:
    // For any admissible inputs where the caller has positive balance, performing a
    // zero-value deposit must NOT change address(c).balance for the reference implementation.
    // The mutant (which uses >=) can behave differently for some inputs; the fuzzer will find them.
    function testFuzz_property(address actor, uint256 firstAmount, uint256 secondAmount) public {
        // keep actor as an EOA and amounts in reasonable range
        vm.assume(actor != address(0));
        // firstAmount must be positive to establish a balance in the contract
        vm.assume(firstAmount > 0);
        // bound amounts to avoid absurdly large values
        firstAmount = bound(firstAmount, 1, 1 ether);
        secondAmount = bound(secondAmount, 0, 1 ether);

        // fund the actor so they can send ETH
        vm.deal(actor, firstAmount + 1 ether);

        // actor makes a nonzero deposit to create state
        vm.startPrank(actor);
        c.deposit{value: firstAmount}();
        // record contract balance after the nonzero deposit
        uint256 balanceAfterFirst = address(c).balance;

        // perform the second deposit (which may be zero)
        c.deposit{value: secondAmount}();
        uint256 balanceAfterSecond = address(c).balance;
        vm.stopPrank();

        // The universal rule we assert: if secondAmount == 0 then the contract balance must be unchanged
        // for the correct implementation. The mutant can accept zero deposits differently and thus
        // change observable behavior; the fuzzer will find such a case and make this assertion fail.
        if (secondAmount == 0) {
            assertTrue(balanceAfterSecond == balanceAfterFirst);
        } else {
            // when secondAmount > 0, the balance should increase by exactly secondAmount
            assertTrue(balanceAfterSecond == balanceAfterFirst + secondAmount);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    function check_deposit_non_decreasing(address who, uint256 v) public {
        // ensure this contract has enough ether to forward the deposit
        require(address(this).balance >= v);

        // read balance before deposit via the public auto-generated getter
        uint256 before = c.balances(who);

        // perform the deposit from this contract to c on behalf of this contract
        // we must call c.deposit paying v; msg.sender inside c will be this contract
        c.deposit{value: v}();

        // read balance after deposit
        uint256 after = c.balances(who);

        // The original contract prevents overflow so the balance for any address
        // can never decrease as a result of a deposit. The mutant removing the
        // overflow check can cause a wrap and make the recorded balance smaller.
        assert(after >= before);
    }

    // allow the test contract to receive ether so it can forward deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address who, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // original contract has an overflow check that rejects deposits which would overflow;
        // in practice that means deposit should revert only if msg.value would cause overflow.
        // The general rule: any strictly positive deposit amount should not revert under C's assert.
        bool reverted;
        try c.deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        // Assert that if amount > 0 then the call did not revert.
        assert(!(amount > 0 && reverted));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address who, uint256 v) public payable {
        require(address(this).balance >= v);
        // try to deposit v from this contract to c
        bool reverted;
        try c.deposit{value: v}() { reverted = false; } catch { reverted = true; }
        // In the original contract, deposit reverts exactly when adding v to the existing balance would overflow.
        // We cannot read balances, but we can observe that when v==0 both versions behave the same (no overflow).
        // The general rule: if v is nonzero, the call must not succeed when it would wrap (i.e., original prevents overflow by assert),
        // so we assert that either the call reverted or v == 0 || !reverted (ensuring non-overflowing deposits succeed).
        // Re-express: if call did not revert then v == 0 || true -- but we must capture overflow behavior via reverted flag and v.
        // A concise general rule that original satisfies and mutant breaks: if v == 0 then deposit must not revert (original does not revert on zero),
        // while mutant also doesn't revert; to distinguish, require that for all v==0 reverted==false.
        assert(v != 0 || reverted == false);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 priorBalance, uint256 value) public payable {
        require(address(this).balance >= value);
        // We cannot read c.balances, so we encode priorBalance as the caller's assumed prior balance
        // by first ensuring caller has transferred priorBalance to c via a sequence: if priorBalance>0 send that amount
        // But we may not perform multiple state-changing calls inside try; instead we check mathematical overflow relation
        // The property: deposit reverts iff priorBalance + value < priorBalance (i.e., overflow)
        bool reverted;
        try c.deposit{value: value}() { reverted = false; } catch { reverted = true; }
        // The invariant: reverted == (priorBalance + value < priorBalance)
        // Expressed without literals: equality between reverted and overflow predicate
        assert(reverted == (priorBalance + value < priorBalance));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address depositor, uint256 amount) public payable {
        // We must fund this test contract so it can forward Ether to c
        require(address(this).balance >= amount);
        // Precondition: depositor is this contract so we can control balances via sending
        // and ensure that depositor's prior balance equals address(c).balance by first
        // transferring the whole c balance back to c from this contract (setup step).
        // To make observable and simple, require depositor == address(this)
        require(depositor == address(this));

        bool reverted;
        // call deposit on c forwarding Ether 'amount'
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: if the amount is so large that adding it to the depositor's prior balance
        // would overflow uint256, the original contract's deposit must revert (reverted == true).
        // We cannot read balances, so express overflow condition via amount > type(uint256).max - address(c).balance
        // Because prior balance of depositor is at most address(c).balance, a sufficient conservative check:
        bool overflow_if_prior_equal_contract = amount > type(uint256).max - address(c).balance;
        assert(!overflow_if_prior_equal_contract || reverted);
    }
    receive() external payable {}
}

