import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero
        vm.assume(depositor != address(0));
        // ensure depositor has funds to send
        vm.deal(depositor, amount);

        // read balance before
        // there's no public getter for mapping unless declared public; use a pattern: call deposit 0 to ensure mapping key exists?
        // But mapping has no getter; however the requirement allows observing via public surface only. The contract C does not expose balances mapping.
        // We can observe behavior via performing deposit and ensuring the operation did not decrease the depositor's effective recorded balance by comparing
        // by making two deposits: first with some small amount, then with fuzzed amount, and then refund to retrieve recorded balance and compare monotonicity.

        // Do a small initial deposit so recorded balance is nonzero and can be observed via refund
        uint256 tiny = 1;
        if (amount == 0) {
            // if amount is zero, still do a tiny deposit from the depositor to establish an initial balance
            vm.deal(depositor, tiny);
            vm.prank(depositor);
            c.deposit{value: tiny}();

            // store observed refunded amount after a subsequent deposit of 0 (should be >= tiny)
            vm.prank(depositor);
            c.deposit{value: 0}();

            // Now refund and observe
            vm.prank(depositor);
            uint256 beforeRefundBal;
            try c.refund() {
                // refund succeeded; the depositor received their balance, we can inspect address balance increase by checking depositor's balance in VM
                // But Test vm does not provide direct prior snapshot; instead we rely on that refund transfers the recorded balance to depositor.
                // To capture refunded amount, we make depositor's balance zero beforehand and compare after - before. Simpler: use two-step: deposit tiny, deposit 0, then refund to get total.
                // For consistency with the single-assert requirement, we will instead perform a sequence where we compare refunded totals before and after performing the fuzzed deposit.
            } catch {
                // shouldn't revert
            }
        }

        // Strategy: 1) make an initial deposit X (tiny) from depositor, then 2) perform fuzzed deposit of amount, then 3) refund and observe total refunded >= X
        // To observe refunded amount we will record depositor's wallet balance delta across refund call.

        // Reset depositor's balance in VM to known amount for accurate delta measurement
        uint256 preFund = amount + 10 ether; // plenty of funds
        vm.deal(depositor, preFund);

        // Step 1: initial small deposit X
        uint256 X = 1;
        vm.prank(depositor);
        c.deposit{value: X}();

        // Step 2: fuzzed deposit
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Step 3: measure depositor balance change when calling refund to get recorded balance back
        uint256 balBefore = depositor.balance;
        vm.prank(depositor);
        c.refund();
        uint256 balAfter = depositor.balance;
        uint256 refunded = balAfter - balBefore;

        // The invariant: refunded (the recorded balance returned by refund) must be >= X
        // This holds in the reference because deposit increments balances and cannot decrease them; overflow in mutant can wrap values making refunded < X for some amount.
        assertTrue(refunded >= X);
    }
}

