pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero EOA-like
        vm.assume(depositor != address(0));
        // ensure depositor has funds to send
        vm.deal(depositor, amount);

        // read old recorded balance via public getter (auto-generated for mapping if public);
        // In original contract mapping is not public, so we cannot call a getter. Instead we observe
        // the invariant using contract's behavior: perform deposit and then perform a refund to recover
        // the recorded balance via transferring out the stored balance. The refund() sets balance to 0 and
        // transfers the recorded amount to msg.sender; so by calling refund() after deposit we can learn
        // what the contract recorded for that depositor.

        // perform deposit as depositor
        vm.prank(depositor);
        c.deposit{value: amount}();

        // now call refund as depositor to learn stored balance: refund transfers recorded balance to caller
        // capture the depositor's balance before refund to compute how much was recorded
        uint256 before = depositor.balance;
        vm.prank(depositor);
        c.refund();
        uint256 afterBalance = depositor.balance;

        uint256 recorded = afterBalance - before;

        // The general rule: recorded == oldRecorded + amount. Since we cannot read oldRecorded directly,
        // we reason from initial state: setUp deployed a fresh contract with zero balances; if the same depositor
        // did a single deposit and then refund, the recorded value should equal amount (no wraparound).
        // Therefore assert recorded == amount.
        assertTrue(recorded == amount);
    }
}

