pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // admissible domain: depositor is not the zero address and amount is > 0
        vm.assume(depositor != address(0));
        vm.assume(amt > 0);

        // fund the depositor so they can send amt
        vm.deal(depositor, amt);

        // get prior balance stored in contract for this depositor via behavior: make a safe initial deposit of 1 if needed
        // ensure prior stored balance is nonzero to avoid triviality
        vm.prank(depositor);
        c.deposit{value: 1}();

        // read prior stored balance by performing a zero-value call to withdraw with try/catch to observe behavior is not allowed
        // there is no getter for balances, but we can infer the stored balance by attempting to withdraw amounts
        // We'll binary-search a bound: try to withdraw amt+1 to see if require(amount <= balances[msg.sender]) permits it
        // However tests must use public surface only; instead we use the fact that withdraw reverts when amount > balance.

        // Determine a value greater than stored balance to locate stored balance range. Start with high = 2**256-1 and low=0
        uint256 low = 0;
        uint256 high = type(uint256).max;
        // We know depositor has at least 1 stored from earlier deposit. Narrow to a manageable number of steps.
        for (uint256 i = 0; i < 128; i++) {
            uint256 mid = low + (high - low) / 2;
            // try withdrawal of mid; success means mid <= balance
            vm.prank(depositor);
            bool ok;
            try c.withdraw(mid) {
                ok = true;
            } catch {
                ok = false;
            }
            if (ok) {
                // mid was withdrawable, so balance >= mid; put low = mid
                low = mid;
                // to avoid draining funds in the test, re-deposit the withdrawn amount back
                // we need to repay depositor so subsequent calls behave consistently
                // repaying: make the depositor send back 'mid' to contract
                vm.deal(depositor, mid);
                vm.prank(depositor);
                c.deposit{value: mid}();
            } else {
                // mid was not withdrawable, so balance < mid
                high = mid;
            }
            if (high - low <= 1) break;
        }

        // After binary search, low is a value withdrawable (<= balance). We want priorBalance = low.
        uint256 priorBalance = low;
        // require priorBalance != 0 per property
        vm.assume(priorBalance != 0);

        // Now perform the fuzzed deposit of amt and observe whether deposit either reverts (assert) or results in stored balance > priorBalance
        bool depositSucceeded;
        vm.prank(depositor);
        try c.deposit{value: amt}() {
            depositSucceeded = true;
        } catch {
            depositSucceeded = false;
        }

        // If deposit succeeded, then the reference ensures balances[msg.sender] > priorBalance.
        // We assert that: either deposit reverted (depositSucceeded == false) OR address(c).balance increased (proxy for stored balance increase)
        // But we must observe contract via public surface. We can check that a withdraw of (priorBalance) still succeeds and withdraw of (priorBalance + 1) succeeds if stored balance increased.

        if (!depositSucceeded) {
            // OK: reference can assert-fail for overflow, so test passes for this input
            assertTrue(true);
            return;
        }

        // deposit succeeded: now check that balance increased strictly (> priorBalance)
        // If stored balance > priorBalance then withdrawing priorBalance+1 should succeed.
        vm.prank(depositor);
        bool canWithdrawMore;
        try c.withdraw(priorBalance + 1) {
            canWithdrawMore = true;
        } catch {
            canWithdrawMore = false;
        }

        // Final single assertion: for the reference, either deposit reverted OR withdraw(priorBalance+1) succeeds
        assertTrue(canWithdrawMore);
    }
}

