        bool ok;
        vm.prank(depositor);
        try c.deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call/attempt, read the recorded balance again
        uint256 after = getBalanceFromC(depositor);

        // General rule: for all admissible inputs (depositor != 0 and prior != 0),
