            // guard to prevent infinite recursion: clear cached before reentering
            uint256 saved = cached;
            cached = 0;
            // attempt to reenter with zero (no-op) to see behavior; wrap in try to avoid bubbling
            try c.withdraw(0) {
            } catch {
            }
            cached = saved;
        }
    }

    // expose cached balance for test's observations
    function cachedBalance() external view returns (uint256) {
        return cached;
    }
}

